import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { heldOn, type Hold } from '../people/usePeople';

/** A claim's status: DRAFT -> OPEN -> SETTLED; a clerk's settle above the clerk limit goes to PENDING
 *  instead, which a steward approves (SETTLED) or rejects (OPEN again); a DRAFT, OPEN or PENDING claim
 *  can become VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A claim: its amount with two decimals, its date (yyyy-mm-dd), its note, its status, its number on
 *  the sheet (given when it is opened: 1, 2, ... or, under period numbering, <period>-<n> or X-<n>; null while a draft and once void) and the due fixed when it was
 *  settled (null unless settled while its grade had a rate: its due is then live, from the rates), and
 *  who opened it (null until it is opened), whether its person's last statement bound it, and the figure
 *  it was bound to (null when not bound, or bound with no figure: its due then stays live), and, for a
 *  correction (a negative amount), the number of the settled claim of the same person it corrects, and
 *  its due-by (yyyy-mm-dd), fixed when it was created from its person's own terms, else the terms of their grade then (else the
 *  sheet's terms), and its status log: a line per status it has had, oldest first, as
 *  "<STATUS> by <user> on <date> due=<due>" with the sheet's today and its due at that moment, and whether
 *  its last statement bound it to n/a (the rate that would apply to it had ended: its due stays n/a), and
 *  the date it is deferred until (null when it was never deferred: see `isDeferred`), and how many proofs it has,
 *  and, for a claim split off another, the number of the claim it was split from (null otherwise), and the user
 *  whose open editor locks it for everyone else (null when it is not locked), and the last day (the sheet's today
 *  then) a reminder was written for it (null when never reminded). */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  dueBy: string;
  statedNa: boolean;
  deferredUntil: string | null;
  proofs: number;
  splitFrom: string | null;
  lateEntry: boolean;
  reminded: string | null;
  ref: string | null;
  log: string[];
  lockedBy: string | null;
};

/** Whether a claim is open: OPEN, or PENDING (handled like OPEN everywhere but its statement binding). */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** A claim's fixed figure: the due frozen when it was settled, else the one its last statement bound
 *  it to (a PENDING claim is not bound; 'n/a' when it bound it to n/a); null when its due is live. */
export function fixedDue(c: Claim): string | null {
  if (c.due !== null) return c.due;
  if (!isBound(c)) return null;
  return c.statedNa ? 'n/a' : c.statedDue;
}

/** Whether a claim is deferred now: it is OPEN and the date it is deferred until is after the sheet's
 *  today. Until today reaches that date it counts in no total, is not overdue and cannot be settled. */
export function isDeferred(c: Claim, today: string | undefined): boolean {
  return c.status === 'OPEN' && c.deferredUntil !== null && today !== undefined && today < c.deferredUntil;
}

/** Whether a claim counts toward claimed and every live total, given the people's holds by person id
 *  and the sheet's today: only open (OPEN or PENDING) and SETTLED claims do, and an open claim dated within
 *  one of its person's holds does not, unless a statement binds it, nor does a deferred one. */
export function counts(c: Claim, holds: ReadonlyMap<number, Hold[]>, today: string | undefined): boolean {
  return c.status === 'SETTLED'
    || (isOpen(c) && !isDeferred(c, today) && (isBound(c) || !heldOn(holds.get(c.personId), c.date)));
}

/** A claim's status at the end of a day (yyyy-mm-dd), as its status log records it: the last line dated
 *  on or before it; null when the claim did not yet exist then. */
export function statusOn(c: Claim, day: string): ClaimStatus | null {
  let status: ClaimStatus | null = null;
  for (const line of c.log) {
    const m = /^(\w+) by .* on (\d{4}-\d{2}-\d{2}) due=/.exec(line);
    if (m && m[2] <= day) status = m[1] as ClaimStatus;
  }
  return status;
}

/** Whether a claim counts toward a period ending on a day: by the live rules (holds, deferral, binding),
 *  applied to the status it had at the end of that day; not when it did not yet exist then. A hold leaves
 *  out only a claim still open now: one since settled or voided counts by the status it had then. */
export function countsOn(c: Claim, day: string, holds: ReadonlyMap<number, Hold[]>, today: string | undefined): boolean {
  const status = statusOn(c, day);
  return status !== null && counts({ ...c, status }, isOpen(c) ? holds : new Map(), today);
}

/** Whether its person's last statement binds a claim now: it was stated and is not PENDING. */
export function isBound(c: Claim): boolean {
  return c.stated && c.status !== 'PENDING';
}

export function claimsKey(sheetId: string) {
  return ['sheet', sheetId, 'claims'];
}

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: async () => {
      const res = await getJson<{
        claims: Omit<Claim, 'log' | 'lockedBy'>[];
        logs: Record<string, string[]>;
        locks: Record<string, string>;
      }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`);
      return res.claims.map((c): Claim => ({
        ...c,
        log: res.logs[String(c.id)] ?? [],
        lockedBy: res.locks[String(c.id)] ?? null,
      }));
    },
  });
}

/** The sum of the amounts of those of these claims that count (given the people's holds by person id and
 *  the sheet's today), with two decimals (added up in cents, so no rounding drift). */
export function claimed(claims: Claim[], holds: ReadonlyMap<number, Hold[]>, today: string | undefined): string {
  const cents = claims.filter((c) => counts(c, holds, today)).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
import { counts, fixedDue, useClaims } from '../claims/useClaims';
import { claimDueNow } from '../overdue/useOverdue';
import { gradeOn, holdsById, usePeople } from '../people/usePeople';
import { settingOn, useSettings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';
import { hundredths, money, rateFor, sumDues, useRates } from './useRates';

/** Each person's due-total, by person id: the sum of the figures of their claims that count (open (OPEN or PENDING)
 *  claims dated within one of their holds left out unless a statement binds them; a settled claim's frozen due, else the figure their last statement
 *  bound it to, else its live due, with its late charge while overdue),
 *  skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today is in force
 *  then and no counting claim of theirs keeps a fixed figure or has a due (at the grade it was claimed under).
 *  A due-total is at most the sheet's cap in force on its today ('n/a' is not capped). */
export function useDueTotals(sheetId: string): Map<number, string> {
  const totals = new Map<number, string>();
  for (const [id, f] of useDueFigures(sheetId)) totals.set(id, f.total);
  return totals;
}

/** Each person's excess, by person id: how far the sum of their figures is above the sheet's cap; 0.00 when
 *  it is not (or there is no cap, or their due-total is 'n/a'). */
export function useExcess(sheetId: string): Map<number, string> {
  const excess = new Map<number, string>();
  for (const [id, f] of useDueFigures(sheetId)) excess.set(id, f.excess);
  return excess;
}

/** Each person's settled-total and open-total, by person id: the sum of the figures of their counting SETTLED
 *  claims, and of their counting open (OPEN or PENDING) claims, as in their due-total ('n/a' figures skipped).
 *  The two add up to the due-total before the cap. */
export function useSettledOpenTotals(sheetId: string): Map<number, { settled: string; open: string }> {
  const split = new Map<number, { settled: string; open: string }>();
  for (const [id, f] of useDueFigures(sheetId)) split.set(id, { settled: f.settled, open: f.open });
  return split;
}

/** Each person's due-total held to the cap, their excess over it, and its settled and open parts. */
function useDueFigures(sheetId: string): Map<number, { total: string; excess: string; settled: string; open: string }> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const today = useSheetToday(sheetId);
  const settings = useSettings(sheetId).data;
  const holds = holdsById(people.data, today.data?.today);
  const cap = settingOn(settings, 'cap', today.data?.today);
  const totals = new Map<number, { total: string; excess: string; settled: string; open: string }>();
  for (const p of people.data ?? []) {
    const counting = (claims.data ?? []).filter((c) => c.personId === p.id && counts(c, holds, today.data?.today));
    const rated = rateFor(rates.data, p.grade, today.data?.today) !== undefined;
    const dues = counting.map((c) =>
      claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(p, c.date), c.date), settings, today.data?.today, gradeOn(p, c.date)));
    const shown = rated || counting.some((c) => fixedDue(c) !== null && fixedDue(c) !== 'n/a') || dues.some((d) => d !== 'n/a');
    const sum = sumDues(dues);
    const over = shown && cap !== null && hundredths(sum) > hundredths(cap);
    totals.set(p.id, {
      total: !shown ? 'n/a' : over ? cap : sum,
      excess: over ? money(hundredths(sum) - hundredths(cap)) : '0.00',
      settled: sumDues(dues.filter((_, i) => counting[i].status === 'SETTLED')),
      open: sumDues(dues.filter((_, i) => counting[i].status !== 'SETTLED')),
    });
  }
  return totals;
}
import { SheetBody } from '../../slots/defs/sheetBody';
import { useActive } from '../active/useActive';
import { useClaims } from '../claims/useClaims';
import { GRADES, usePeople } from '../people/usePeople';
import { usePeriodDueTotals } from '../periods/usePeriodDueTotals';
import { usePeriods } from '../periods/usePeriods';
import { useDueTotals } from '../rates/useDueTotals';
import { sumDues } from '../rates/useRates';
import { countWithStatus, STATUSES } from './statusCounts';

/** The sheet's summary, worked out from the same figures the lists show: per grade, how many people
 *  have it on the sheet's today (retired people left out) and their due-totals added up (skipping
 *  'n/a') and how many of them are active; per period, its due-total; per status, how many claims have it. */
function Summary({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const periods = usePeriods(sheetId);
  const dueTotals = useDueTotals(sheetId);
  const periodTotals = usePeriodDueTotals(sheetId);
  const activeById = useActive(sheetId);
  const current = (people.data ?? []).filter((p) => !p.retiredFrom);
  return (
    <section data-testid="summary">
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due total</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const onGrade = current.filter((p) => p.grade === g);
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{onGrade.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>
                  {sumDues(onGrade.map((p) => dueTotals.get(p.id) ?? 'n/a'))}
                </td>
                <td data-testid={`summary-grade-${g}-active`}>
                  {onGrade.filter((p) => activeById.get(p.id)).length}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due total</th>
          </tr>
        </thead>
        <tbody>
          {(periods.data ?? []).map((p) => (
            <tr key={p.id}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>{periodTotals.get(p.name) ?? ''}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>
                {countWithStatus(claims.data, s)}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 40, Component: ({ sheetId }) => <Summary sheetId={sheetId} /> });
import { defineSlot } from '../Slot';

/**
 * The body of the active sheet, rendered once a user is signed in and a sheet is loaded. A
 * feature that shows or changes a sheet's data fills this region. Its data lives under query
 * keys starting ['sheet', sheetId, ...]: loading a sheet drops every such key, so the whole
 * sheet is re-read from the store.
 */
export const SheetBody = defineSlot<{ sheetId: string; user: string }>('sheet.body');
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}

